// Smallest Enclosing Circle — Hierarchy, route: jsx
// Source: d3-packenclose
//
// Self-contained: every local import is inlined below. Requires only d3, react.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { useMemo } from 'react';
import * as d3 from 'd3';

const MARGIN = 14;
const MAX_HEIGHT = 560;
const CIRCLE_COUNT = 64;
const SEED = 0x9e3779b9;
const MIN_RADIUS = 6;
const RADIUS_SPREAD = 20;
/** Fraction of the enclosing radius within which a circle counts as tangent to it. */
const TANGENT_TOLERANCE = 0.002;
const CAPTION_MIN_WIDTH = 380;

type Circle = { id: number; r: number };

/** mulberry32 — a fixed seed keeps the packing identical across reloads. */
function seededRadii(count: number, seed: number): number[] {
  let state = seed;
  return Array.from({ length: count }, () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let x = Math.imul(state ^ (state >>> 15), 1 | state);
    x = (x + Math.imul(x ^ (x >>> 7), 61 | x)) ^ x;
    return MIN_RADIUS + (((x ^ (x >>> 14)) >>> 0) / 4294967296) * RADIUS_SPREAD;
  });
}

/** One radius per circle to pack, in pixels. */
export type Data = number[];

const DEMO: Data = seededRadii(CIRCLE_COUNT, SEED);

export default function PackEnclose({ data = DEMO, width }: { data?: Data; width: number }) {
  const height = Math.min(width, MAX_HEIGHT);

  const circles = useMemo(
    () => d3.packSiblings<Circle>(data.map((r, id) => ({ id, r }))),
    [data]
  );

  const enclosing = useMemo(() => d3.packEnclose(circles), [circles]);

  const fillOpacity = useMemo(
    () =>
      d3
        .scaleLinear()
        .domain([d3.min(circles, (c) => c.r) ?? 0, d3.max(circles, (c) => c.r) ?? 1])
        .range([0.9, 0.3]),
    [circles]
  );

  // A circle touches the enclosure when its centre distance plus its radius reaches
  // the enclosing radius; those circles are the basis d3.packEnclose solves for.
  const isTangent = useMemo(() => {
    const slack = enclosing.r * TANGENT_TOLERANCE;
    return new Set(
      circles
        .filter((c) => Math.hypot(c.x - enclosing.x, c.y - enclosing.y) + c.r >= enclosing.r - slack)
        .map((c) => c.id)
    );
  }, [circles, enclosing]);

  if (width === 0) return null;

  const captionHeight = width >= CAPTION_MIN_WIDTH ? 20 : 0;
  const scale = (Math.min(width, height - captionHeight) / 2 - MARGIN) / enclosing.r;

  return (
    <svg
      viewBox={`${-width / 2} ${-height / 2} ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Sixty-four circles of varying radii packed against one another by d3.packSiblings, wrapped in the smallest enclosing circle computed by d3.packEnclose, with the circles tangent to that enclosure outlined"
    >
      <g
        transform={`translate(0,${-captionHeight / 2}) scale(${scale}) translate(${-enclosing.x},${-enclosing.y})`}
      >
        <circle
          cx={enclosing.x}
          cy={enclosing.y}
          r={enclosing.r}
          fill="none"
          stroke="var(--text)"
          strokeWidth={1.5 / scale}
          strokeDasharray={`${6 / scale} ${5 / scale}`}
        />
        {circles.map((c) => (
          <circle
            key={c.id}
            cx={c.x}
            cy={c.y}
            r={c.r}
            fill="var(--accent)"
            fillOpacity={fillOpacity(c.r)}
            stroke={isTangent.has(c.id) ? 'var(--text)' : 'none'}
            strokeWidth={1.5 / scale}
          />
        ))}
      </g>
      {width >= CAPTION_MIN_WIDTH && (
        <text
          x={0}
          y={height / 2 - 6}
          textAnchor="middle"
          fontSize={11}
          fill="var(--muted)"
        >
          Dashed: the smallest enclosing circle. Outlined: the circles tangent to it.
        </text>
      )}
    </svg>
  );
}
